+    let (mut client, _server) = render_grpc_client().await;
+    let prompt_token_ids =
+        render_tokenize(&render_service(), plain_chat_request()).await.prompt_token_ids;
+    let (requests, request_stream) = futures::channel::mpsc::unbounded();
